    if (!row) throw new Error("Purchase not found");
    const payCheck = database_default.prepare("SELECT paidAmount FROM supplier_purchases WHERE id = ?").get(id3);
    if (payCheck && payCheck.paidAmount > 0) {
      throw new Error("Cannot delete a purchase with payments. Delete payments first.");
    }
    const transaction = database_default.transaction(() => {
      const items = database_default.prepare("SELECT * FROM supplier_purchase_items WHERE purchaseId = ?").all(id3);
      const defWhId = getDefaultWarehouseId2();
      for (const it of items) {
        if (!it.itemId) continue;
        const receivedQty = it.receivedQuantity || 0;
        if (receivedQty > 0) {
          database_default.prepare("UPDATE items SET totalBaseQuantity = MAX(0, totalBaseQuantity - ?) WHERE id = ?").run(receivedQty, it.itemId);
          database_default.prepare("UPDATE warehouse_inventory SET quantity = MAX(0, quantity - ?) WHERE warehouseId = ? AND itemId = ?").run(receivedQty, defWhId, it.itemId);
          database_default.prepare("INSERT INTO stock_movements (warehouseId, itemId, type, quantity, referenceId, referenceType, notes) VALUES (?, ?, ?, ?, ?, ?, ?)").run(defWhId, it.itemId, "purchase_reversal", -receivedQty, id3, "supplier_purchase", `Reversed purchase #${id3} - ${it.itemName}`);
        }
      }
      database_default.prepare("DELETE FROM supplier_purchase_items WHERE purchaseId = ?").run(id3);
      database_default.prepare("DELETE FROM supplier_purchases WHERE id = ?").run(id3);
    });
    transaction();
    logSupplierActivity(row.supplierId, "purchase_deleted", "supplier_purchase", id3, `Purchase ${row?.purchaseNumber || id3} deleted`);
