  import_electron14.ipcMain.handle("insert-supplier-payment", (_, data) => {
    requirePermission("purchases.edit");
    if (!data.supplierId) throw new Error("Supplier is required");
    if (!data.paymentDate) throw new Error("Payment date is required");
    const amount = validatePositive(data.amount, "Amount");
    const validMethods = ["cash", "bank_transfer", "mobile_money", "check", "other"];
    if (!validMethods.includes(data.paymentMethod)) throw new Error("Invalid payment method");
    const bizId = getActiveBusinessId();
    const insertTxn = database_default.transaction(() => {
      const targetPurchaseId = data.purchaseId || null;
      let effectivePurchaseId = targetPurchaseId;
      if (!effectivePurchaseId) {
        const oldestOutstanding = database_default.prepare(`
          SELECT id, totalAmount - paidAmount AS remaining
          FROM supplier_purchases
          WHERE supplierId = ? AND businessId = ? AND status != 'cancelled' AND (totalAmount - paidAmount) > 0
          ORDER BY purchaseDate ASC, id ASC
          LIMIT 1
        `).get(data.supplierId, bizId);
        if (oldestOutstanding) {
          effectivePurchaseId = oldestOutstanding.id;
        }
      }
      const res = database_default.prepare(`
        INSERT INTO supplier_payments (
          businessId, supplierId, purchaseId, paymentDate,
          referenceNumber, amount, paymentMethod, notes
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      `).run(
        bizId,
        data.supplierId,
        effectivePurchaseId,
        data.paymentDate,
        data.referenceNumber || null,
        amount,
        data.paymentMethod,
        data.notes || null
      );
      if (effectivePurchaseId) {
        database_default.prepare(`
          UPDATE supplier_purchases SET paidAmount = paidAmount + ?, updatedAt = CURRENT_TIMESTAMP WHERE id = ?
        `).run(amount, effectivePurchaseId);
        const remaining = database_default.prepare("SELECT totalAmount - paidAmount AS r FROM supplier_purchases WHERE id = ?").get(effectivePurchaseId);
        if (remaining && remaining.r <= 0) {
          database_default.prepare("UPDATE supplier_purchases SET status = 'received' WHERE id = ? AND status NOT IN ('cancelled')").run(effectivePurchaseId);
        }
      }
      return res.lastInsertRowid;
    });
    const id3 = insertTxn();
    logSupplierActivity(data.supplierId, "payment_recorded", "supplier_payment", Number(id3), `Payment of ${amount} recorded via ${data.paymentMethod}`);
    return { id: id3 };
  });
  import_electron14.ipcMain.handle("update-supplier-payment", (_, id3, data) => {
    requirePermission("purchases.edit");
    const oldPayment = database_default.prepare("SELECT * FROM supplier_payments WHERE id = ?").get(id3);
    if (!oldPayment) throw new Error("Payment not found");
    const amount = validatePositive(data.amount, "Amount");
    const validMethods = ["cash", "bank_transfer", "mobile_money", "check", "other"];
    if (!validMethods.includes(data.paymentMethod)) throw new Error("Invalid payment method");
    const purchaseId = data.purchaseId ? Number(data.purchaseId) : oldPayment.purchaseId;
    const updateTxn = database_default.transaction(() => {
      database_default.prepare(`
        UPDATE supplier_payments SET
          paymentDate = ?, referenceNumber = ?, amount = ?,
          paymentMethod = ?, notes = ?, purchaseId = ?
        WHERE id = ?
      `).run(
        data.paymentDate,
        data.referenceNumber || null,
        amount,
        data.paymentMethod,
        data.notes || null,
        purchaseId,
        id3
      );
      if (purchaseId) {
        const totalPaid = database_default.prepare("SELECT COALESCE(SUM(amount), 0) AS tp FROM supplier_payments WHERE purchaseId = ? AND id != ?").get(purchaseId, id3).tp;
        const newPaid = totalPaid + amount;
        database_default.prepare("UPDATE supplier_purchases SET paidAmount = ?, updatedAt = CURRENT_TIMESTAMP WHERE id = ?").run(newPaid, purchaseId);
        const remaining = database_default.prepare("SELECT totalAmount - paidAmount AS r FROM supplier_purchases WHERE id = ?").get(purchaseId);
        if (remaining && remaining.r <= 0) {
          database_default.prepare("UPDATE supplier_purchases SET status = 'received' WHERE id = ? AND status NOT IN ('cancelled')").run(purchaseId);
        } else if (remaining && remaining.r > 0) {
          database_default.prepare("UPDATE supplier_purchases SET status = 'pending' WHERE id = ? AND status = 'received'").run(purchaseId);
        }
      }
    });
    updateTxn();
    return { success: true };
  });
