  import_electron14.ipcMain.handle("void-sale", async (event, data) => {
    requirePermission("sales.void");
    const reason = (data?.reason || "").trim();
    if (!reason) throw new Error("A reason is required to void a sale");
    if (!await gateSensitiveAction(event.sender, { context: `Void sale #${data.saleId}` })) {
      throw new Error("Manager approval required \u2014 action not executed");
    }
    const sale = database_default.prepare("SELECT * FROM sales WHERE id = ?").get(data.saleId);
    if (!sale) throw new Error("Sale not found");
    if (sale.status === "Voided") throw new Error("Sale is already voided");
    const item = database_default.prepare("SELECT * FROM items WHERE id = ?").get(sale.itemId);
    const transaction = database_default.transaction(() => {
      if (item) {
        let baseRestore = sale.quantity;
        let packRestore = 0;
        if (sale.unitType === "pack") {
          baseRestore = sale.quantity * (item.unitsPerPack || 1);
          packRestore = sale.quantity;
        } else {
          packRestore = Math.round(sale.quantity / (item.unitsPerPack || 1) * 1e6) / 1e6;
        }
        database_default.prepare("UPDATE items SET totalBaseQuantity = totalBaseQuantity + ?, totalPackQuantity = totalPackQuantity + ? WHERE id = ?").run(baseRestore, packRestore, sale.itemId);
        const defWhId = getDefaultWarehouseId2();
        const whRow = database_default.prepare("SELECT id FROM warehouse_inventory WHERE warehouseId = ? AND itemId = ?").get(defWhId, sale.itemId);
        if (whRow) {
          database_default.prepare("UPDATE warehouse_inventory SET quantity = quantity + ?, updatedAt = CURRENT_TIMESTAMP WHERE id = ?").run(baseRestore, whRow.id);
        } else {
          database_default.prepare("INSERT INTO warehouse_inventory (warehouseId, itemId, quantity) VALUES (?, ?, ?)").run(defWhId, sale.itemId, baseRestore);
        }
        database_default.prepare("INSERT INTO stock_movements (warehouseId, itemId, type, quantity, referenceType, notes) VALUES (?, ?, ?, ?, ?, ?)").run(defWhId, sale.itemId, "void_restore", baseRestore, "void", `Sale #${data.saleId} voided \u2014 stock restored`);
      }
      database_default.prepare("UPDATE sales SET status = 'Voided', voidReason = ?, voidedBy = ?, voidedAt = CURRENT_TIMESTAMP WHERE id = ?").run(data.reason, currentUserName || "unknown", data.saleId);
      if ((sale.paidAmount || 0) > 0) {
        database_default.prepare("UPDATE sales SET paidAmount = 0, paymentStatus = ? WHERE id = ?").run(sale.totalPrice > 0 ? "Debt" : "Pending", data.saleId);
      }
    });
    transaction();
    insertAuditLog("void_sale", "sale", data.saleId, "status", "Active", "Voided", `Sale #${data.saleId} voided by ${currentUserName || "unknown"}. Reason: ${data.reason}`);
    return database_default.prepare("SELECT * FROM sales WHERE id = ?").get(data.saleId);
  });
