  import_electron14.ipcMain.handle("convert-order-to-sale", (_, data) => {
    requirePermission("orders.convert");
    data = validate(orderConversionSchema, data, "order conversion");
    const bizId = getActiveBusinessId();
    const order = database_default.prepare("SELECT * FROM orders WHERE id = ? AND businessId = ? AND is_deleted = 0").get(data.orderId, bizId);
    if (!order) throw new Error("Order not found");
    if (order.status !== "Order") throw new Error('Only orders with status "Order" can be converted');
    const items = database_default.prepare("SELECT * FROM order_items WHERE orderId = ?").all(data.orderId);
    const transaction = database_default.transaction(() => {
      const saleIds = [];
      for (const item of items) {
        const dbItem = database_default.prepare("SELECT * FROM items WHERE id = ?").get(item.itemId);
        if (!dbItem) throw new Error(`Item "${item.itemName}" not found in inventory`);
        const qty = item.quantity;
        let baseDeduction = qty;
        let packDeduction = 0;
        if (item.unitType === "pack") {
          baseDeduction = qty * (dbItem.unitsPerPack || 1);
          packDeduction = qty;
        } else {
          packDeduction = Math.round(qty / (dbItem.unitsPerPack || 1) * 1e6) / 1e6;
        }
        const itemResult = database_default.prepare("UPDATE items SET totalBaseQuantity = totalBaseQuantity - ?, totalPackQuantity = totalPackQuantity - ? WHERE id = ? AND totalBaseQuantity >= ?").run(baseDeduction, packDeduction, item.itemId, baseDeduction);
        if (itemResult.changes === 0) throw new Error(`Insufficient stock: ${dbItem.name} has less than ${baseDeduction} units available`);
        const itemDiscount = data.discount ? item.totalPrice / order.totalAmount * data.discount : 0;
        const itemVat = data.vat ? item.totalPrice / order.totalAmount * data.vat : 0;
        const finalPrice = item.totalPrice - itemDiscount + itemVat;
        const saleResult = database_default.prepare(`
          INSERT INTO sales (businessId, itemId, quantity, unit, unitType, discount, vat, totalPrice, paymentMethod, paymentStatus, customerName, customerPhone, createdBy)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'Paid', ?, ?, ?)
        `).run(bizId, item.itemId, qty, item.unit || "pcs", item.unitType || "base", itemDiscount, itemVat, finalPrice, data.paymentMethod || "Cash", order.customerName || null, order.customerPhone || null, null);
        saleIds.push(saleResult.lastInsertRowid);
        const defWhId = getDefaultWarehouseId2();
        const whResult = database_default.prepare("UPDATE warehouse_inventory SET quantity = quantity - ?, updatedAt = CURRENT_TIMESTAMP WHERE warehouseId = ? AND itemId = ? AND quantity >= ?").run(baseDeduction, defWhId, item.itemId, baseDeduction);
        if (whResult.changes === 0) {
          const whExists = database_default.prepare("SELECT id FROM warehouse_inventory WHERE warehouseId = ? AND itemId = ?").get(defWhId, item.itemId);
          if (!whExists) {
            database_default.prepare("INSERT INTO warehouse_inventory (warehouseId, itemId, quantity) VALUES (?, ?, ?)").run(defWhId, item.itemId, -baseDeduction);
          } else {
            throw new Error(`Insufficient stock at warehouse: ${dbItem.name} has less than ${baseDeduction} units available`);
          }
        }
        database_default.prepare("INSERT INTO stock_movements (warehouseId, itemId, type, quantity, referenceType, notes) VALUES (?, ?, ?, ?, ?, ?)").run(defWhId, item.itemId, "sale_out", baseDeduction, "order_conversion", `Converted from order ${order.orderNumber}`);
      }
      database_default.prepare("UPDATE orders SET status = 'Converted', convertedAt = CURRENT_TIMESTAMP, convertedBy = ? WHERE id = ?").run(currentUserName || "unknown", data.orderId);
      database_default.prepare("INSERT INTO order_history (orderId, action, performedBy, notes) VALUES (?, ?, ?, ?)").run(data.orderId, "converted_to_sale", currentUserName || "unknown", `Converted to sale(s): ${saleIds.join(", ")}. Payment: ${data.paymentMethod || "Cash"}`);
      return { success: true, saleIds };
    });
    const result = transaction();
    insertAuditLog("convert_order_to_sale", "order", data.orderId, "status", "Order", "Converted", `Order #${data.orderId} converted to sale by ${currentUserName || "unknown"}`);
    return result;
  });
